package solution

import "testing"

func TestNewPowersOfThreeSequenceAndExhaustion(t *testing.T) {
	g := NewPowersOfThree()
	var values []uint64
	for {
		v, ok := g()
		if !ok {
			if v != 0 {
				t.Fatalf("exhausted generator returned %d, false", v)
			}
			break
		}
		values = append(values, v)
	}
	if len(values) != 41 {
		t.Fatalf("generated %d values, want 41", len(values))
	}
	if values[0] != 1 || values[len(values)-1] != 12157665459056928801 {
		t.Fatalf("unexpected endpoints: %d, %d", values[0], values[len(values)-1])
	}
	for i := 1; i < len(values); i++ {
		if values[i] != values[i-1]*3 {
			t.Fatalf("value %d = %d, want %d", i, values[i], values[i-1]*3)
		}
	}
	for i := 0; i < 3; i++ {
		if v, ok := g(); ok || v != 0 {
			t.Fatalf("post-exhaustion call %d = (%d, %v)", i, v, ok)
		}
	}
}

func TestGeneratorsHaveIndependentState(t *testing.T) {
	a := NewPowersOfThree()
	b := NewPowersOfThree()
	av, aok := a()
	av2, aok2 := a()
	bv, bok := b()
	if av != 1 || !aok || av2 != 3 || !aok2 || bv != 1 || !bok {
		t.Fatalf("independence results: a=(%d,%v),(%d,%v), b=(%d,%v)", av, aok, av2, aok2, bv, bok)
	}
}

func TestPowersOfThreeBoundariesAndFreshResults(t *testing.T) {
	for _, n := range []int{-2, 0} {
		got := PowersOfThree(n)
		if got == nil || len(got) != 0 {
			t.Errorf("PowersOfThree(%d) = %#v, want non-nil empty", n, got)
		}
	}
	got := PowersOfThree(5)
	want := []uint64{1, 3, 9, 27, 81}
	if len(got) != len(want) {
		t.Fatalf("PowersOfThree(5) = %#v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("PowersOfThree(5) = %#v", got)
		}
	}
	got[0] = 999
	again := PowersOfThree(2)
	if len(again) != 2 || again[0] != 1 || again[1] != 3 {
		t.Fatalf("later result shares state: %#v", again)
	}
	all := PowersOfThree(100)
	if len(all) != 41 || all[40] != 12157665459056928801 {
		t.Fatalf("exhaustion result has len %d and last %d", len(all), all[len(all)-1])
	}
}

package solution

import "testing"

func TestReviewBoundedGenerator0204(t *testing.T) {
	defer func() { if p := recover(); p != nil { t.Errorf("bounded output panicked: %v", p) } }()
	values := PowersOfThree(int(^uint(0)>>1))
	if len(values) != 41 || values[0] != 1 || values[40] != 12157665459056928801 {
		t.Fatalf("incorrect bounded power sequence: %v", values)
	}
}

